/* PR c/8086  */

#define P(x) \
        ((((((((((((((((((((((((((((((((        \
         (x)+a)                 \
         *(x)+a)                 \
         *(x)+a)                 \
         *(x)+a)                 \
         *(x)+a)                 \
         *(x)+a)                 \
         *(x)+a)                 \
